{
  "themes": [
    {
      "cluster": 24,
      "name": "OnePlus Exchange and EMI Issues",
      "description": "Customers complain about confusing exchange offers, higher-than-advertised no‑cost EMI rates, and difficulty accessing special promotions for OnePlus devices."
    },
    {
      "cluster": 25,
      "name": "Excessive Packaging Waste",
      "description": "Customers criticize oversized or unnecessary cardboard packaging for small items, calling for smaller, more sustainable boxes."
    },
    {
      "cluster": 26,
      "name": "Unexpected or Duplicate Charges",
      "description": "Customers report being billed twice, charged extra fees, or seeing unexplained charges on their accounts."
    },
    {
      "cluster": 27,
      "name": "Gift Card Balance and Transfer Problems",
      "description": "Customers experience issues adding, redeeming, or transferring gift card balances across accounts and regions."
    },
    {
      "cluster": 28,
      "name": "Amazon Pay Withdrawal and Usage Restrictions",
      "description": "Customers are unable to move funds from Amazon Pay to bank accounts, use balances for purchases, or understand hold policies."
    },
    {
      "cluster": 29,
      "name": "Missing Cashback Rewards",
      "description": "Customers claim they did not receive promised cashback on purchases or promotional offers."
    },
    {
      "cluster": 30,
      "name": "Wrong or Damaged Item Delivery",
      "description": "Customers receive incorrect, damaged, or missing products and struggle to get replacements or refunds."
    },
    {
      "cluster": 31,
      "name": "Poor Customer Service Experience",
      "description": "Customers describe unhelpful, slow, or rude support interactions, often involving callbacks and unresolved issues."
    },
    {
      "cluster": 32,
      "name": "General Frustration and Unclear Support Channels",
      "description": "Customers express confusion and irritation about how to get help, often using profanity and vague requests."
    },
    {
      "cluster": 33,
      "name": "Delayed Refund Processing",
      "description": "Customers report long wait times for refunds after returns, with unclear timelines and missing funds."
    },
    {
      "cluster": 34,
      "name": "Order Cancellation Difficulties",
      "description": "Customers face technical problems canceling orders, receive unexpected cancellations, or lack explanations for canceled purchases."
    },
    {
      "cluster": 35,
      "name": "Extremely Negative Customer Service Feedback",
      "description": "Customers use strong language to describe consistently terrible support, including hangs‑up calls and broken promises."
    }
  ]
}
